import React, { Component } from 'react';

class CountryTable extends Component {
    constructor(props) {
        super(props);
        this.state = {
            countries: [
                { name: "India", capital: "New Delhi" },
                { name: "USA", capital: "Washington D.C." },
                { name: "Japan", capital: "Tokyo" }
            ]
        };
    }

    render() {
        return (
            <div>
                <h2>Country List</h2>
                <table border="1">
                    <thead>
                        <tr>
                            <th>Country</th>
                            <th>Capital</th>
                        </tr>
                    </thead>
                    <tbody>
                        {this.state.countries.map((c, index) => (
                            <tr key={index}>
                                <td>{c.name}</td>
                                <td>{c.capital}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        );
    }
}

export default CountryTable;
